LEVELS = ["A1", "A2", "B1", "B2", "C1", "C2"]

def unit(level, n, title, grammar, vocab):
    return CurriculumUnit(id=f"ha-{level.lower()}-{n}", level=level, unit_number=n, title=f"Hausa {level} · {title}", grammar_points=[grammar], vocabulary_set_ids=[vocab], lesson_types=["grammar","vocabulary","listening","speaking","reading","writing","review"], competency_checklist=["Understand authentic Hausa input at this level","Produce accurate Hausa in context"], default_weeks=2)

